"""Sitting settings from YAML (Frame Pool read; Annotation / labels write roots)."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path

import yaml


class ConfigError(Exception):
    """Sitting config file missing or invalid."""


def _repo_root() -> Path:
    return Path(__file__).resolve().parents[1]


_OLD_TOOL = Path("/data3/yky/sam3_1_label_tool")


def _default_annotations_root() -> Path:
    return _repo_root() / "data" / "mask"


def _default_labels_root() -> Path:
    return _repo_root() / "data" / "labels"


def _default_sam31_repo() -> Path:
    # SAM code stays in the old tree; this repo does not vendor sam3/.
    return _OLD_TOOL / "sam3"


def _default_sam31_checkpoint() -> Path:
    return _OLD_TOOL / "sam31_label_kit" / "ckpt" / "sam3.1_multiplex.pt"


@dataclass(frozen=True)
class ClipEntry:
    id: str
    kind: str
    path: Path


@dataclass(frozen=True)
class Settings:
    frames_root: Path
    clip_allowlist: tuple[str, ...]
    clips: tuple[ClipEntry, ...] = ()
    annotations_root: Path = field(default_factory=_default_annotations_root)
    labels_root: Path = field(default_factory=_default_labels_root)
    auto_save_on_propagate: bool = True
    # Derived cache root for lazy JPEG transcode (labels_root.parent / "video-cache").
    video_cache_root: Path | None = None
    # Worker / SAM 3.1 (ticket 07). Default backend is fake (no GPU; CI).
    predictor_backend: str = "fake"  # "fake" | "sam31"
    sam31_checkpoint: Path = field(default_factory=_default_sam31_checkpoint)
    sam31_repo: Path = field(default_factory=_default_sam31_repo)
    gpu_id: int | None = None
    # Scribble Model worker (ADR 0009). Default fake: no GPU in CI.
    scribble_backend: str = "fake"  # "fake" | "scribble"
    scribble_model_path: Path | None = None
    scribble_sam2_checkpoint: Path | None = None
    # None / unset SCRIBBLE_GPU_ID: share this Session's gpu_id. Do not default 0/1/5.
    scribble_gpu_id: int | None = None
    # Coordination SQLite (WAL). None → labels_root.parent / "coordination.sqlite".
    coordination_db: Path | None = None
    session_cookie_secure: bool = False


def default_config_path() -> Path:
    return _repo_root() / "config.yaml"


def _resolve_path(raw: str, base: Path) -> Path:
    path = Path(raw).expanduser()
    if not path.is_absolute():
        path = base / path
    return path.resolve()


def _clip_allowlist(value: object, path: Path) -> tuple[str, ...]:
    if value is None:
        return ()
    if isinstance(value, str):
        name = value.strip()
        return (name,) if name else ()
    if isinstance(value, list):
        return tuple(str(item).strip() for item in value if str(item).strip())
    raise ConfigError(f"{path}: clip_allowlist must be a list of Clip ids")


def _parse_clips(value: object, path: Path, base: Path) -> tuple[ClipEntry, ...]:
    if value is None:
        return ()
    if not isinstance(value, list):
        raise ConfigError(f"{path}: clips must be a list")
    entries: list[ClipEntry] = []
    for item in value:
        if not isinstance(item, dict):
            raise ConfigError(f"{path}: each clips entry must be a mapping")
        clip_id = str(item.get("id") or "").strip()
        kind = str(item.get("kind") or "").strip()
        raw_path = item.get("path")
        if not clip_id or not kind or raw_path is None or not str(raw_path).strip():
            continue
        entries.append(ClipEntry(id=clip_id, kind=kind, path=_resolve_path(str(raw_path).strip(), base)))
    return tuple(entries)


def _parse_backend(
    value: object, path: Path, key: str, allowed: tuple[str, ...], default: str
) -> str:
    if value is None:
        return default
    text = str(value).strip()
    if text not in allowed:
        raise ConfigError(f"{path}: {key} must be one of {' / '.join(allowed)}")
    return text


def _optional_path(value: object, base: Path) -> Path | None:
    if value is None or not str(value).strip():
        return None
    return _resolve_path(str(value).strip(), base)


def _optional_int(value: object, path: Path, key: str) -> int | None:
    if value is None:
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        raise ConfigError(f"{path}: {key} must be an integer") from None


def load_settings(config_path: Path | str | None = None) -> Settings:
    path = Path(config_path) if config_path is not None else default_config_path()
    if not path.is_file():
        raise ConfigError(
            f"config file not found: {path}\n"
            "Sitting reads repo-root config.yaml or --config PATH. "
            "It does not read FRAMES_ROOT / CLIP_ALLOWLIST / other env."
        )

    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8"))
    except yaml.YAMLError as exc:
        raise ConfigError(f"invalid YAML in {path}: {exc}") from exc
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise ConfigError(f"invalid YAML in {path}: expected a mapping")

    base = path.parent
    clips = _parse_clips(data.get("clips"), path, base)
    frames_raw = data.get("frames_root")
    if frames_raw is None or not str(frames_raw).strip():
        if not clips:
            raise ConfigError(f"{path}: frames_root is required")
        frames_root = clips[0].path if clips[0].kind == "jpeg" else clips[0].path.parent
    else:
        frames_root = _resolve_path(str(frames_raw).strip(), base)

    labels_raw = data.get("labels_root")
    if labels_raw is None or not str(labels_raw).strip():
        labels_root = _default_labels_root()
    else:
        labels_root = _resolve_path(str(labels_raw).strip(), base)

    ann_raw = data.get("annotations_root")
    if ann_raw is None or not str(ann_raw).strip():
        annotations_root = _default_annotations_root()
    else:
        annotations_root = _resolve_path(str(ann_raw).strip(), base)

    cache_raw = data.get("video_cache_root")
    if cache_raw is None or not str(cache_raw).strip():
        video_cache_root = None
    else:
        video_cache_root = _resolve_path(str(cache_raw).strip(), base)

    allowlist = tuple(entry.id for entry in clips) if clips else _clip_allowlist(data.get("clip_allowlist"), path)

    coord_raw = data.get("coordination_db")
    if coord_raw is None or not str(coord_raw).strip():
        coordination_db = None
    else:
        coordination_db = _resolve_path(str(coord_raw).strip(), base)

    secure_raw = data.get("session_cookie_secure")
    session_cookie_secure = bool(secure_raw)

    return Settings(
        frames_root=frames_root,
        clip_allowlist=allowlist,
        clips=clips,
        annotations_root=annotations_root,
        labels_root=labels_root,
        video_cache_root=video_cache_root,
        predictor_backend=_parse_backend(
            data.get("predictor_backend"), path, "predictor_backend", ("fake", "sam31"), "fake"
        ),
        sam31_checkpoint=_optional_path(data.get("sam31_checkpoint"), base)
        or _default_sam31_checkpoint(),
        sam31_repo=_optional_path(data.get("sam31_repo"), base) or _default_sam31_repo(),
        gpu_id=_optional_int(data.get("gpu_id"), path, "gpu_id"),
        scribble_backend=_parse_backend(
            data.get("scribble_backend"), path, "scribble_backend", ("fake", "scribble"), "fake"
        ),
        scribble_model_path=_optional_path(data.get("scribble_model_path"), base),
        scribble_sam2_checkpoint=_optional_path(data.get("scribble_sam2_checkpoint"), base),
        scribble_gpu_id=_optional_int(data.get("scribble_gpu_id"), path, "scribble_gpu_id"),
        coordination_db=coordination_db,
        session_cookie_secure=session_cookie_secure,
    )

"""Compose four backends: phase, class, triplet, mask. Mask Session is optional."""

from __future__ import annotations

from pathlib import Path

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse

from endo_label.auth import install_auth, router as auth_router
from endo_label.config import Settings, load_settings
from endo_label.frame_class.router import make_router as class_router
from endo_label.mask.http import create_app as create_mask_app
from endo_label.mask.session import SessionManager
from endo_label.phase.router import make_router as phase_router
from endo_label.triplet.router import make_router as triplet_router
from endo_label.vocab_router import make_router as vocab_router

_DEFAULT_WEB_DIST = Path(__file__).resolve().parents[1] / "web" / "dist"


def _desk_file(dist: Path, relative: str) -> Path | None:
    if not relative or relative.endswith("/"):
        return None
    root = dist.resolve()
    candidate = (root / relative).resolve()
    try:
        candidate.relative_to(root)
    except ValueError:
        return None
    return candidate if candidate.is_file() else None


def _mount_built_desk(app: FastAPI, dist: Path) -> None:
    index = dist / "index.html"
    if not index.is_file():
        return

    @app.get("/", include_in_schema=False)
    def desk_root() -> FileResponse:
        return FileResponse(index)

    @app.get("/{full_path:path}", include_in_schema=False)
    def desk_spa(full_path: str) -> FileResponse:
        if full_path == "api" or full_path.startswith("api/"):
            raise HTTPException(status_code=404, detail="Not Found")
        found = _desk_file(dist, full_path)
        if found is not None:
            return FileResponse(found)
        return FileResponse(index)


def create_app(
    settings: Settings | None = None,
    web_dist: Path | None = None,
    session_manager: SessionManager | None = None,
):
    cfg = settings if settings is not None else load_settings()
    app = create_mask_app(cfg, session_manager=session_manager)
    install_auth(app)
    app.include_router(auth_router)
    app.include_router(phase_router(cfg))
    app.include_router(class_router(cfg))
    app.include_router(triplet_router(cfg))
    app.include_router(vocab_router(cfg))
    app.state.backends = ("phase", "class", "triplet", "mask")
    _mount_built_desk(app, web_dist if web_dist is not None else _DEFAULT_WEB_DIST)
    return app

"""Read-only Clip catalog over a Frame Pool allowlist."""

from __future__ import annotations

import shutil
import subprocess
from dataclasses import dataclass
from pathlib import Path

from endo_label.config import ClipEntry, Settings

_JPEG_SUFFIXES = {".jpg", ".jpeg", ".JPG", ".JPEG"}
JPEG_CLOCK_FPS = 25


@dataclass(frozen=True)
class FrameRef:
    index: int
    stem: str
    path: Path


class CatalogError(Exception):
    """Base catalog failure."""


class ClipNotFound(CatalogError):
    pass


class FrameNotFound(CatalogError):
    pass


class TranscodeError(CatalogError):
    """JPEG Clip could not be transcoded to mp4."""


def clip_entries(settings: Settings) -> tuple[ClipEntry, ...]:
    if settings.clips:
        return settings.clips
    return tuple(
        ClipEntry(id=clip_id, kind="jpeg", path=settings.frames_root / clip_id)
        for clip_id in settings.clip_allowlist
    )


def _entry(settings: Settings, clip_id: str) -> ClipEntry:
    for entry in clip_entries(settings):
        if entry.id == clip_id:
            return entry
    raise ClipNotFound(clip_id)


def _clip_dir(settings: Settings, clip_id: str) -> Path:
    entry = _entry(settings, clip_id)
    if entry.kind != "jpeg":
        raise ClipNotFound(clip_id)
    path = entry.path.resolve()
    if not settings.clips:
        if clip_id in ("", ".", "..") or "/" in clip_id or "\\" in clip_id:
            raise ClipNotFound(clip_id)
        try:
            path.relative_to(settings.frames_root.resolve())
        except ValueError as exc:
            raise ClipNotFound(clip_id) from exc
    if not path.is_dir():
        raise ClipNotFound(clip_id)
    return path


def _list_frame_files(clip_dir: Path) -> list[Path]:
    files = [
        p
        for p in clip_dir.iterdir()
        if p.is_file() and p.suffix in _JPEG_SUFFIXES
    ]

    def sort_key(p: Path) -> int:
        try:
            return int(p.stem)
        except ValueError:
            # Non-integer stems sort after all integer stems, by name
            return 10**18

    files.sort(key=lambda p: (sort_key(p), p.stem))
    return files


def list_frames(settings: Settings, clip_id: str) -> list[FrameRef]:
    files = _list_frame_files(_clip_dir(settings, clip_id))
    return [FrameRef(index=i, stem=p.stem, path=p) for i, p in enumerate(files)]


def _read_u32(fh, offset: int) -> int | None:
    fh.seek(offset)
    data = fh.read(4)
    if len(data) < 4:
        return None
    return int.from_bytes(data, "big")


def _boxes(fh, start: int, end: int):
    offset = start
    while offset + 8 <= end:
        size = _read_u32(fh, offset)
        fh.seek(offset + 4)
        typ = fh.read(4)
        if size is None or len(typ) < 4:
            break
        if size == 1:
            fh.seek(offset + 8)
            ext = fh.read(8)
            if len(ext) < 8:
                break
            size = int.from_bytes(ext, "big")
            header = 16
        elif size == 0:
            size = end - offset
            header = 8
        else:
            header = 8
        if size < 8 or offset + size > end:
            break
        yield typ, offset + header, offset + size
        offset += size


def _mvhd_seconds(fh, start: int, end: int) -> float | None:
    if end - start < 20:
        return None
    fh.seek(start)
    version = fh.read(1)[0]
    if version == 1:
        if end - start < 32:
            return None
        timescale = _read_u32(fh, start + 20)
        fh.seek(start + 24)
        duration_raw = fh.read(8)
        if timescale is None or len(duration_raw) < 8:
            return None
        duration = int.from_bytes(duration_raw, "big")
    else:
        timescale = _read_u32(fh, start + 12)
        duration = _read_u32(fh, start + 16)
        if timescale is None or duration is None:
            return None
    if timescale <= 0:
        return None
    return duration / timescale


def _stts_delta(fh, start: int, end: int) -> int | None:
    if end - start < 16:
        return None
    count = _read_u32(fh, start + 4)
    if not count:
        return None
    delta = _read_u32(fh, start + 12)
    return delta if delta and delta > 0 else None


def _mdhd_timescale(fh, start: int, end: int) -> int | None:
    if end - start < 20:
        return None
    fh.seek(start)
    version = fh.read(1)[0]
    if version == 1:
        if end - start < 24:
            return None
        return _read_u32(fh, start + 20)
    return _read_u32(fh, start + 12)


def _trak_fps(fh, start: int, end: int) -> int | None:
    timescale = None
    delta = None
    vide = False
    for typ, inner_start, inner_end in _boxes(fh, start, end):
        if typ != b"mdia":
            continue
        for inner, media_start, media_end in _boxes(fh, inner_start, inner_end):
            if inner == b"mdhd":
                timescale = _mdhd_timescale(fh, media_start, media_end)
            elif inner == b"minf":
                for leaf, leaf_start, leaf_end in _boxes(fh, media_start, media_end):
                    if leaf == b"vmhd":
                        vide = True
                    elif leaf == b"stbl":
                        for table, table_start, table_end in _boxes(fh, leaf_start, leaf_end):
                            if table == b"stts":
                                delta = _stts_delta(fh, table_start, table_end)
    if not vide or not timescale or not delta:
        return None
    return max(1, round(timescale / delta))


def _mp4_clock(path: Path) -> tuple[float | None, int | None]:
    seconds = None
    fps = None

[194 more lines in file. Use offset=201 to continue.]

    fps = None
    with path.open("rb") as fh:
        size = path.stat().st_size
        for typ, start, end in _boxes(fh, 0, size):
            if typ != b"moov":
                continue
            for inner, inner_start, inner_end in _boxes(fh, start, end):
                if inner == b"mvhd":
                    seconds = _mvhd_seconds(fh, inner_start, inner_end)
                elif inner == b"trak" and fps is None:
                    fps = _trak_fps(fh, inner_start, inner_end)
    return seconds, fps


def video_clock(path: Path) -> tuple[int, int]:
    """Return (frame_count, fps). fps is container fps, else 25."""
    fps = JPEG_CLOCK_FPS
    try:
        seconds, parsed_fps = _mp4_clock(path)
    except OSError:
        return 0, fps
    if parsed_fps:
        fps = parsed_fps
    if seconds is None:
        return 0, fps
    return max(1, round(seconds * fps)), fps


def video_path(settings: Settings, clip_id: str) -> Path:
    entry = _entry(settings, clip_id)
    if entry.kind != "video":
        raise ClipNotFound(clip_id)
    path = entry.path.resolve()
    if not path.is_file():
        raise ClipNotFound(clip_id)
    return path


def video_cache_root(settings: Settings) -> Path:
    if settings.video_cache_root is not None:
        return settings.video_cache_root
    return settings.labels_root.parent / "video-cache"


def _cache_is_fresh(cache: Path, clip_dir: Path, frames: list[Path]) -> bool:
    if not cache.is_file():
        return False
    cache_mtime = cache.stat().st_mtime
    if cache_mtime < clip_dir.stat().st_mtime:
        return False
    return all(cache_mtime >= frame.stat().st_mtime for frame in frames)


def _concat_escape(path: Path) -> str:
    return str(path.resolve()).replace("'", "'\\''")


def _run_transcode(frames: list[Path], out: Path, ffmpeg: str) -> None:
    """Encode the Frame list (in Frame order) to a 25 fps mp4 at ``out``."""
    list_path = out.with_suffix(".list")
    list_path.write_text(
        "ffconcat version 1.0\n"
        + "\n".join(
            f"file '{_concat_escape(frame)}'\nduration 0.04" for frame in frames
        )
        + "\n",
        encoding="utf-8",
    )
    try:
        proc = subprocess.run(
            [
                ffmpeg,
                "-y",
                "-f",
                "concat",
                "-safe",
                "0",
                "-i",
                str(list_path),
                "-c:v",
                "libx264",
                "-pix_fmt",
                "yuv420p",
                "-vf",
                "scale=trunc((iw+1)/2)*2:trunc((ih+1)/2)*2",
                "-r",
                "25",
                "-movflags",
                "+faststart",
                "-an",
                str(out),
            ],
            capture_output=True,
            text=True,
            timeout=180,
        )
        if proc.returncode != 0:
            tail = "\n".join(proc.stderr.splitlines()[-12:])
            raise TranscodeError(f"ffmpeg transcode failed: {tail}")
    except subprocess.TimeoutExpired as exc:
        raise TranscodeError("ffmpeg transcode timed out") from exc
    finally:
        list_path.unlink(missing_ok=True)


def ensure_transcoded(settings: Settings, clip_id: str) -> Path:
    """Return a playable mp4 for a JPEG Clip, transcoding lazily when stale."""
    entry = _entry(settings, clip_id)
    if entry.kind != "jpeg":
        raise ClipNotFound(clip_id)
    clip_dir = _clip_dir(settings, clip_id)
    frames = [frame.path for frame in list_frames(settings, clip_id)]
    if not frames:
        raise TranscodeError(f"Clip {clip_id} has no JPEG frames")
    cache_dir = video_cache_root(settings)
    cache_dir.mkdir(parents=True, exist_ok=True)
    cache = cache_dir / f"{clip_id}.mp4"
    if _cache_is_fresh(cache, clip_dir, frames):
        return cache
    ffmpeg = shutil.which("ffmpeg")
    if ffmpeg is None:
        raise TranscodeError(
            "ffmpeg not found on PATH; install ffmpeg to play JPEG Clips"
        )
    tmp = cache.with_name(f"{clip_id}.tmp.mp4")
    _run_transcode(frames, tmp, ffmpeg)
    tmp.replace(cache)
    return cache


def media_path(settings: Settings, clip_id: str) -> Path:
    """Source media for playback: video file, or the transcoded JPEG cache."""
    entry = _entry(settings, clip_id)
    if entry.kind == "video":
        return video_path(settings, clip_id)
    return ensure_transcoded(settings, clip_id)


def _clip_row(entry: ClipEntry, settings: Settings) -> dict | None:
    if entry.kind == "jpeg":
        try:
            frames = list_frames(settings, entry.id)
        except ClipNotFound:
            return None
        return {
            "id": entry.id,
            "kind": "jpeg",
            "frame_count": len(frames),
            "fps": JPEG_CLOCK_FPS,
        }
    if entry.kind == "video":
        path = entry.path.resolve()
        if not path.is_file():
            return None
        frame_count, fps = video_clock(path)
        return {
            "id": entry.id,
            "kind": "video",
            "frame_count": frame_count,
            "fps": fps,
        }
    return None


def list_clips(settings: Settings) -> list[dict]:
    clips: list[dict] = []
    for entry in clip_entries(settings):
        row = _clip_row(entry, settings)
        if row is not None:
            clips.append(row)
    return clips


def clip_meta(settings: Settings, clip_id: str) -> dict:
    entry = _entry(settings, clip_id)
    row = _clip_row(entry, settings)
    if row is None:
        raise ClipNotFound(clip_id)
    if entry.kind == "video":
        return {**row, "frames": []}
    frames = list_frames(settings, clip_id)
    return {
        **row,
        "frames": [{"index": f.index, "stem": f.stem} for f in frames],
    }


def frame_path(settings: Settings, clip_id: str, frame_index: int) -> Path:
    if frame_index < 0:
        raise FrameNotFound(f"{clip_id}[{frame_index}]")
    frames = list_frames(settings, clip_id)
    if frame_index >= len(frames):
        raise FrameNotFound(f"{clip_id}[{frame_index}]")
    return frames[frame_index].path

"""Login HTTP: server-side session cookie and /api/me."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException, Request, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel

from endo_label.coordination import (
    Account,
    account_for_session,
    authenticate,
    create_session,
    db_path,
    delete_session,
)

SESSION_COOKIE = "session_id"

router = APIRouter()

_PUBLIC_API = frozenset({"/api/health", "/api/auth/login", "/api/auth/logout"})


class LoginBody(BaseModel):
    username: str
    password: str


def _me(account: Account) -> dict:
    return {
        "username": account.username,
        "roles": {
            "admin": account.admin,
            "reviewer": account.reviewer,
            "annotator": account.annotator,
        },
    }


def install_auth(app) -> None:
    @app.middleware("http")
    async def require_account(request: Request, call_next):
        path = request.url.path
        if (
            request.method == "OPTIONS"
            or not path.startswith("/api/")
            or path in _PUBLIC_API
        ):
            return await call_next(request)
        settings = request.app.state.settings
        token = request.cookies.get(SESSION_COOKIE)
        account = account_for_session(db_path(settings), token) if token else None
        if account is None or account.disabled:
            return JSONResponse({"detail": "Not authenticated"}, status_code=401)
        request.state.account = account
        return await call_next(request)


@router.post("/api/auth/login")
def login(body: LoginBody, response: Response, request: Request) -> dict:
    settings = request.app.state.settings
    path = db_path(settings)
    account = authenticate(path, body.username, body.password)
    if account is None:
        raise HTTPException(status_code=401, detail="Not authenticated")
    token = create_session(path, account.id)
    response.set_cookie(
        key=SESSION_COOKIE,
        value=token,
        httponly=True,
        samesite="lax",
        secure=settings.session_cookie_secure,
        path="/",
    )
    return _me(account)


@router.post("/api/auth/logout")
def logout(request: Request, response: Response) -> dict:
    token = request.cookies.get(SESSION_COOKIE)
    if token:
        delete_session(db_path(request.app.state.settings), token)
    response.delete_cookie(SESSION_COOKIE, path="/")
    return {"ok": True}


@router.get("/api/me")
